@extends('layouts.admin') @section('page',$type==='job'?'درخواست‌های کاری':'فروشندگان و مصالح') @section('admin-content')<div class="admin-page-heading"><div><h1>{{ $type==='job'?'مدیریت درخواست‌های کاری':'فروشندگان و آگهی‌های مصالح' }}</h1><p>بررسی محتوا، تأیید انتشار و رسیدگی به آگهی‌های نامناسب</p></div><span class="tag">{{ \App\Support\Format::number($records->total()) }} آگهی</span></div><form class="filters panel"><x-field name="q" label="عنوان آگهی" :value="request('q')"/><div class="field"><label for="status">وضعیت</label><select name="status" id="status"><option value="">همه وضعیت‌ها</option>@foreach(['pending','in_review','published','draft','rejected','inactive','completed','cancelled'] as $status)<option value="{{ $status }}" @selected(request('status')===$status)>{{ \App\Support\Format::status($status) }}</option>@endforeach</select></div><button class="button compact">جستجو</button><a class="text-link" href="{{ route('admin.listings',$type) }}">پاک‌کردن</a></form><div class="moderation-list">@forelse($records as $record)<article class="panel review-row"><div class="review-info"><span class="tag {{ $record->status }}">{{ \App\Support\Format::status($record->status) }}</span><h3><a href="{{ $type==='job'?route('jobs.show',$record):route('products.show',$record) }}">{{ $record->title??$record->name }}</a></h3><div class="meta"><span>{{ $record->category->name }}</span><span><x-icon name="pin" size="15"/>{{ $record->city }}</span><a class="gold" href="{{ route('admin.users.show',$record->user) }}">{{ $record->user->full_name }}</a></div><p>{{ \Illuminate\Support\Str::limit($record->description??$record->specifications,150) }}</p><a class="text-link" href="{{ $type==='job'?route('jobs.show',$record):route('products.show',$record) }}">مشاهده کامل آگهی <x-icon name="arrow" size="15"/></a></div><form method="post" action="{{ in_array($record->status,['pending','in_review'])?route('admin.moderate',[$type,$record->id]):route('admin.listing.status',[$type,$record